{{ config(
            materialized='table',
                post_hook={
                    "sql": "INSERT INTO SNITCH_DB.MAPLEMONK.SPEED_INVENTORY with data as ( select CASE WHEN BRANCH_CODE = 42 THEN \'SNITCH - COFO - METRO MALL\' WHEN BRANCH_CODE = 26 THEN \'SNITCH - COFO - LINKING ROAD\' WHEN BRANCH_CODE = 68 THEN \'SNITCH - COFO - DAHISAR\' WHEN BRANCH_CODE = 142 THEN \'SNITCH - COCO - HINJAWADI PHASE -1\' WHEN BRANCH_CODE = 23 THEN \'SNITCH - COFO - TRIBECA\' WHEN BRANCH_CODE = 38 THEN \'SNITCH - COFO - BANER\' WHEN BRANCH_CODE = 90 THEN \'SNITCH - COCO - JANAKPURI\' WHEN BRANCH_CODE = 106 THEN \'SNITCH - COCO - MOTI NAGAR\' WHEN BRANCH_CODE = 49 THEN \'SNITCH - COCO - LAJPAT NAGAR\' WHEN BRANCH_CODE = 82 THEN \'SNITCH - COCO - FARIDABAD\' WHEN BRANCH_CODE = 73 THEN \'SNITCH - COCO - SECTOR-29\' WHEN BRANCH_CODE = 85 THEN \'SNITCH - COCO - SECTOR-50\' WHEN BRANCH_CODE = 77 THEN \'SNITCH - COFO - TOLICHOWKI\' WHEN BRANCH_CODE = 47 THEN \'SNITCH - COFO - KOTHAPET\' WHEN BRANCH_CODE = 125 THEN \'SNITCH - COFO - HIMAYAT NAGAR\' WHEN BRANCH_CODE = 103 THEN \'SNITCH - FOCO - SINDHUBHAVAN\' WHEN BRANCH_CODE = 18 THEN \'SNITCH - FOCO - SHYAMAL\' WHEN BRANCH_CODE = 134 THEN \'SNITCH - COCO - CG ROAD\' WHEN BRANCH_CODE = 102 THEN \'SNITCH - FOCO - BOPAL\' WHEN BRANCH_CODE = 39 THEN \'SNITCH - FOCO - VAISHALI NAGAR\' WHEN BRANCH_CODE = 91 THEN \'SNITCH - FOCO - MALVIYA NAGAR\' WHEN BRANCH_CODE = 132 THEN \'SNITCH - COCO - KAMLANAGAR\' WHEN BRANCH_CODE = 114 THEN \'SNITCH - COCO - ROHINI\' WHEN BRANCH_CODE = 40 THEN \'SNITCH - FOCO - C ROAD JODHPUR\' WHEN BRANCH_CODE = 57 THEN \'SNITCH - COCO - BANASHANKARI\' WHEN BRANCH_CODE = 14 THEN \'SNITCH - COCO - BEL ROAD\' else null end as store, branch_code, sku, inventory_atp::INTEGER as atp, inventory_total::INTEGER as total, sku_inventory_buffer::INTEGER as sku_buffer, location_inventory_buffer::INTEGER as location_buffer, location_visible, enabled, location, query_hour_ist::DATE as saved_date from snitch_db.maplemonk.s3_product_inventory where store is not null and sku not like \'8%\' and sku not like \'%CB%\' and sku not like \'%HANG%\' and sku not like \'%UNI%\' and sku not like \'%NT%\' and sku not like \'%GIFT%\' ) , buffer as ( select sku_group, branch_code from snitch_db.maplemonk.omni_buffer_skus ), item_master as ( select sku as s1, b.sku_group, b.branch_code as b2, \'true\' as exposure from snitch_db.maplemonk.uc_final_item_master u left join buffer b on u.skugroup = b.sku_group where sku_group is not null ) , correct_inv as ( select branch_code, location, location_visible, sku, sum(total) as total, from data group by 1,2,3,4 ), buffermaths as ( select c.* , CASE WHEN b.exposure = \'true\' and lower(location) not like \'%front%\' then \'true\' WHEN b.exposure = \'true\' and lower(location) like \'%front%\' then \'front\' else \'not_in_list\' end as exposure from correct_inv c left join item_master b on CONCAT(c.branch_code,c.sku) = CONCAT(b.b2,b.s1) ), uc as (select sku, category_code, skugroup, shopify_status, sku_class, sales_last_7_days, sales_last_15_days, sales_last_30_days, natural_ros from snitch_db.maplemonk.uc_final_item_master) select CASE WHEN BRANCH_CODE = 42 THEN \'SNITCH - COFO - METRO MALL\' WHEN BRANCH_CODE = 26 THEN \'SNITCH - COFO - LINKING ROAD\' WHEN BRANCH_CODE = 68 THEN \'SNITCH - COFO - DAHISAR\' WHEN BRANCH_CODE = 142 THEN \'SNITCH - COCO - HINJAWADI PHASE -1\' WHEN BRANCH_CODE = 23 THEN \'SNITCH - COFO - TRIBECA\' WHEN BRANCH_CODE = 38 THEN \'SNITCH - COFO - BANER\' WHEN BRANCH_CODE = 90 THEN \'SNITCH - COCO - JANAKPURI\' WHEN BRANCH_CODE = 106 THEN \'SNITCH - COCO - MOTI NAGAR\' WHEN BRANCH_CODE = 49 THEN \'SNITCH - COCO - LAJPAT NAGAR\' WHEN BRANCH_CODE = 82 THEN \'SNITCH - COCO - FARIDABAD\' WHEN BRANCH_CODE = 73 THEN \'SNITCH - COCO - SECTOR-29\' WHEN BRANCH_CODE = 85 THEN \'SNITCH - COCO - SECTOR-50\' WHEN BRANCH_CODE = 77 THEN \'SNITCH - COFO - TOLICHOWKI\' WHEN BRANCH_CODE = 47 THEN \'SNITCH - COFO - KOTHAPET\' WHEN BRANCH_CODE = 125 THEN \'SNITCH - COFO - HIMAYAT NAGAR\' WHEN BRANCH_CODE = 103 THEN \'SNITCH - FOCO - SINDHUBHAVAN\' WHEN BRANCH_CODE = 18 THEN \'SNITCH - FOCO - SHYAMAL\' WHEN BRANCH_CODE = 134 THEN \'SNITCH - COCO - CG ROAD\' WHEN BRANCH_CODE = 102 THEN \'SNITCH - FOCO - BOPAL\' WHEN BRANCH_CODE = 39 THEN \'SNITCH - FOCO - VAISHALI NAGAR\' WHEN BRANCH_CODE = 91 THEN \'SNITCH - FOCO - MALVIYA NAGAR\' WHEN BRANCH_CODE = 132 THEN \'SNITCH - COCO - KAMLANAGAR\' WHEN BRANCH_CODE = 114 THEN \'SNITCH - COCO - ROHINI\' WHEN BRANCH_CODE = 40 THEN \'SNITCH - FOCO - C ROAD JODHPUR\' WHEN BRANCH_CODE = 57 THEN \'SNITCH - COCO - BANASHANKARI\' WHEN BRANCH_CODE = 14 THEN \'SNITCH - COCO - BEL ROAD\' else null end as store, m.*, uc.category_code, uc.skugroup, uc.shopify_status, uc.sku_class, uc.sales_last_7_days, uc.sales_last_15_days, uc.sales_last_30_days, uc.natural_ros, current_date as saved_date from buffermaths m left join uc on m.sku = uc.sku ; CREATE OR REPLACE TABLE SNITCH_DB.MAPLEMONK.SPEED_ORDER_PROCESSING AS WITH op_dedup AS ( SELECT * FROM ( SELECT op.*, ROW_NUMBER() OVER ( PARTITION BY op.channel_order_number::TEXT ORDER BY op.created_at DESC NULLS LAST ) AS rn FROM SNITCH_DB.MAPLEMONK.OMNI_ORDER_PROCESSING_META op WHERE op.branch_code IN ( \'14\',\'57\',\'68\',\'26\',\'42\',\'38\',\'142\',\'23\',\'49\',\'73\', \'82\',\'85\',\'90\',\'106\',\'114\',\'132\',\'103\',\'18\',\'134\',\'102\' ) ) x WHERE rn = 1 ), app_edd_dedup AS ( SELECT * FROM ( SELECT shopify_order_number::TEXT AS order_number, NULLIF(max_edd, \'\')::TIMESTAMP_NTZ AS app_edd, NULLIF(max_edd, \'\')::DATE AS edd, _airbyte_emitted_at, _airbyte_normalized_at, ROW_NUMBER() OVER ( PARTITION BY shopify_order_number::TEXT ORDER BY _airbyte_emitted_at DESC NULLS LAST, _airbyte_normalized_at DESC NULLS LAST, NULLIF(max_edd, \'\')::TIMESTAMP_NTZ DESC NULLS LAST ) AS rn FROM SNITCH_DB.MAPLEMONK.APP_EDD_DATA WHERE NULLIF(max_edd, \'\') IS NOT NULL ) x WHERE rn = 1 ), cp_dedup AS ( SELECT * FROM ( SELECT cp.*, ROW_NUMBER() OVER ( PARTITION BY cp.awb_number::TEXT ORDER BY cp.assigned_date DESC NULLS LAST, cp.latest_timestamp DESC NULLS LAST, cp.pickup_date DESC NULLS LAST, cp.outfordelivery_date DESC NULLS LAST, cp.delivery_date DESC NULLS LAST ) AS rn FROM SNITCH_DB.MAPLEMONK.CP_1 cp WHERE cp.mode = \'Forward\' ) x WHERE rn = 1 ), base AS ( SELECT op.channel_order_number::TEXT AS order_number, op.channel_order_id, op.channel_order_line_item_id, op.facility_switch, op.store_name, op.region, op.cluster, op.branch_code, op.order_status, op.created_at, op.cancelled_at, NULLIF(op.cancelled_by, \'\') AS cancelled_by, NULLIF(op.cancelled_reason, \'\') AS cancelled_reason, op.pick_list_created_at, op.pick_list_completed, op.packed_at, op.manifested_at, op.dispatched_at, op.tat, op.sku, op.uc_sku, op.product_name, op.category, op.location, op.quantity, op.payment_mode, op.payment_method, op.total_price, op.price, op.cp_name, op.awb, op.shipping_city, op.shipping_state, op.shipping_pincode, op.customer_email, op.customer_phone, op.allocation_rule_id, op.is_quick_com, op.qcom_sla_type, op.qcom_sla_target_ts, op.qcom_sla_minutes, e.app_edd, e.edd, cp.awb_number, cp.assigned_date, cp.pickup_date, cp.delivery_date, cp.outfordelivery_date, cp.out_for_delivery_attempts, cp.latest_timestamp, cp.latest_remark, cp.status AS cp_status, cp.order_id AS cp_order_id, cp.courier_partner, cp.max_sla, cp.min_sla, cp.edd_cp, cp.invoice_value, cp.pincode, cp.mapped_city, cp.mapped_state, cp.pickup_pincode, cp.rto_mark_date, op.created_at::DATE AS created_date_ist, op.created_at::TIME AS created_time_ist, DATEDIFF(day, op.created_at::DATE, e.edd) AS delivery_eta FROM op_dedup op INNER JOIN app_edd_dedup e ON e.order_number = op.channel_order_number::TEXT LEFT JOIN cp_dedup cp ON cp.awb_number::TEXT = op.awb::TEXT WHERE e.edd IS NOT NULL and op.qcom_sla_type is null ), final AS ( SELECT b.*, DATEADD(minute, 690, b.edd) AS sdd_cutoff_ts, CASE WHEN b.created_time_ist >= \'11:00:00\'::TIME AND b.created_time_ist < \'17:00:00\'::TIME THEN DATEADD(minute, 1050, b.created_date_ist) ELSE DATEADD(minute, 690, DATEADD(day, 1, b.created_date_ist)) END AS ndd_cutoff_ts, CURRENT_TIMESTAMP()::TIMESTAMP_NTZ AS now_ist, COALESCE( b.pickup_date, b.outfordelivery_date ) AS effective_handover_ts FROM base b WHERE b.delivery_eta IN (0, 1) AND COALESCE(b.cp_name, \'\') NOT ILIKE \'%Pidge%\' AND COALESCE(b.cp_name, \'\') NOT ILIKE \'%HLD%\' AND COALESCE(b.cp_name, \'\') NOT ILIKE \'%Porter%\' AND COALESCE(b.courier_partner, \'\') NOT ILIKE \'%Pidge%\' AND COALESCE(b.courier_partner, \'\') NOT ILIKE \'%HLD%\' AND COALESCE(b.courier_partner, \'\') NOT ILIKE \'%Porter%\' ), status_tagging AS ( SELECT f.*, CASE WHEN f.delivery_eta = 0 THEN CASE WHEN f.manifested_at IS NOT NULL AND f.manifested_at <= f.sdd_cutoff_ts THEN \'SDD PROCESSING ADHERED\' WHEN f.manifested_at IS NULL AND f.now_ist <= f.sdd_cutoff_ts THEN \'SDD PROCESSING PENDING\' WHEN ( f.manifested_at IS NULL AND f.now_ist > f.sdd_cutoff_ts ) OR ( f.manifested_at IS NOT NULL AND f.manifested_at > f.sdd_cutoff_ts ) THEN \'SDD PROCESSING BREACHED\' END WHEN f.delivery_eta = 1 THEN CASE WHEN f.manifested_at IS NOT NULL AND f.manifested_at <= f.ndd_cutoff_ts THEN \'NDD PROCESSING ADHERED\' WHEN f.manifested_at IS NULL AND f.now_ist <= f.ndd_cutoff_ts THEN \'NDD PROCESSING PENDING\' WHEN ( f.manifested_at IS NULL AND f.now_ist > f.ndd_cutoff_ts ) OR ( f.manifested_at IS NOT NULL AND f.manifested_at > f.ndd_cutoff_ts ) THEN \'NDD PROCESSING BREACHED\' END END AS sla_status, CASE WHEN f.effective_handover_ts IS NULL THEN \'HANDOVER PENDING\' WHEN f.delivery_eta = 0 THEN CASE WHEN f.effective_handover_ts > f.sdd_cutoff_ts THEN \'HANDOVER BREACHED\' ELSE \'HANDOVER COMPLETED\' END WHEN f.delivery_eta = 1 THEN CASE WHEN f.effective_handover_ts > f.ndd_cutoff_ts THEN \'HANDOVER BREACHED\' ELSE \'HANDOVER COMPLETED\' END END AS handover_status, CASE WHEN f.delivery_date IS NULL THEN \'NOT DELIVERED\' WHEN f.delivery_date::DATE <= f.edd THEN \'DELIVERY ADHERED\' ELSE \'DELIVERY BREACHED\' END AS delivery_status FROM final f ) SELECT s.*, CASE WHEN s.sla_status ILIKE \'%BREACHED%\' THEN s.sla_status WHEN s.handover_status = \'HANDOVER BREACHED\' THEN s.handover_status WHEN s.delivery_status = \'DELIVERY BREACHED\' THEN s.delivery_status WHEN s.sla_status ILIKE \'%PENDING%\' THEN s.sla_status WHEN s.handover_status = \'HANDOVER PENDING\' THEN s.handover_status ELSE \'WITHIN TAT\' END AS rca FROM status_tagging s ORDER BY s.delivery_eta, s.created_at;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from snitch_db.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            